import{_ as e,o,c as n,a3 as s}from"./chunks/framework.iKZ1V-y0.js";const g=JSON.parse('{"title":"1.3 Glossary (Even I Cannot Fully Define These; You Can Skip It)","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"1\\\\.3 术语表（我自己也没法完全定义清楚，不看也罢）","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=FBJt940VrXTDHkr5w3g0v3","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-FBJt940VrXTDHkr5w3g0v3.md","filePath":"logistics/src/page-FBJt940VrXTDHkr5w3g0v3.md","lastUpdated":null}'),i={name:"logistics/src/page-FBJt940VrXTDHkr5w3g0v3.md"};function a(r,t,p,c,l,u){return o(),n("div",null,[...t[0]||(t[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-3-术语表-我自己也没法完全定义清楚-不看也罢" aria-hidden="true"></span><h1 id="_1-3-glossary-even-i-cannot-fully-define-these-you-can-skip-it" tabindex="-1">1.3 Glossary (Even I Cannot Fully Define These; You Can Skip It) <a class="header-anchor" href="#_1-3-glossary-even-i-cannot-fully-define-these-you-can-skip-it" aria-label="Permalink to &quot;1\\.3 Glossary (Even I Cannot Fully Define These; You Can Skip It)&quot;">​</a></h1><blockquote><p>Source page ID: <code>FBJt940VrXTDHkr5w3g0v3</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=FBJt940VrXTDHkr5w3g0v3" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><strong>Automatic production switching:</strong> a production line changes its production plan without manual player intervention.</p><p><strong>Material</strong> (for now): inputs or finished products in production, including solids, liquids, and gases.</p><p><strong>Node:</strong> a concrete or abstract location in a line, such as a machine input/output, Conduit Outlet, or belt endpoint.</p><p><strong>Input/output node:</strong> if node a is on a line&#39;s boundary and all material passing through it enters the specified subline, it is an input node; if all passing material leaves that subline, it is an output node.</p><p><strong>Logistics network:</strong> connected logistics components such as belts, pipes, conduits, splitters, and convergers, with one or more definite input and output nodes.</p><p><strong>Path:</strong> a path exists from input a to output b if some blocked or unblocked state permits material transport from a to b. Compare the logistics-path concept in damping theory.</p><p><strong>Immediate upstream/downstream:</strong> if machine A&#39;s output connects to logistics input a, logistics output b connects to machine B&#39;s input, and a path exists from a to b, A is immediately upstream of the logistics network, which is immediately upstream of B.</p><p><strong>Upstream:</strong> a machine/network&#39;s immediate upstream, its upstream&#39;s immediate upstream, and so on.</p><p><strong>Downstream:</strong> a machine/network&#39;s immediate downstream, its downstream&#39;s immediate downstream, and so on.</p><p><strong>Production network:</strong> one or more machines connected with logistics networks, with one or more definite input and output nodes. Upstream/downstream are defined similarly.</p><p><strong>Overflow routing:</strong> where one input has paths to several outputs, blocking some outputs redirects material previously leaving them to other outputs.</p><p><strong>Oversupply:</strong> connected unloaders for an input *30/min exceed the production network&#39;s consumption of that input. With sufficient oversupply, the connecting logistics network remains blocked.</p><p><strong>Output priority:</strong> a game behavior where, with Convergers connected to a stash or Conduit Outlet Manifold, incoming material preferentially exits the lower-damping side. See Section Two, Output Priority, of <a href="./page-oWvEDex0yuejzwpcwzyxUP">Introduction to Analyzing Endfield Logistics Bugs</a>.</p><p><strong>Source of blocking:</strong> the first node to block, furthest downstream of all the blockages.</p><p><a href="./page-vjw47WlrDGyaYlemKyfnH8">1.2 What Are the Benefits of Blocking-Based Production?</a></p><p><a href="./page-0iirIEzxWlkfel2jMLIWJJ">Production Control and Frontier Research</a></p></div>',1)])])}const m=e(i,[["render",a]]);export{g as __pageData,m as default};
